# file: test_solution.py
from flat import flatten, unflatten

# --- Tests for flatten ---

# Basic functionality
assert flatten({}) == {}
assert flatten({"a": 1}) == {"a": 1}
assert flatten({"a": {"b": 1}, "c": 2}) == {"a.b": 1, "c": 2}
assert flatten({"a": {"b": {"c": {"d": 4}}}}) == {"a.b.c.d": 4}

# Empty nested dicts (should be kept as {})
assert flatten({"a": {}}) == {"a": {}}
assert flatten({"a": {"b": {}}}) == {"a.b": {}}

# Custom separator
assert flatten({"a": {"b": 1}}, sep="/") == {"a/b": 1}

# Non-dict containers (should be treated as leaves)
assert flatten({"a": [1, 2], "b": {"c": [3]}}) == {"a": [1, 2], "b.c": [3]}

# Order preservation (depth-first insertion order)
assert list(flatten({"z": {"y": 1, "x": 2}, "a": 3})) == ["z.y", "z.x", "a"]

# Error handling: Non-string keys
try:
    flatten({1: "a"})
    assert False, "Should raise TypeError for non-string keys"
except TypeError as e:
    assert str(e) == "keys must be strings"

# --- Tests for unflatten ---

# Basic functionality (Inverse of flatten)
assert unflatten({"a.b": 1, "c": 2}) == {"a": {"b": 1}, "c": 2}
assert unflatten({"a.b.c.d": 4}) == {"a": {"b": {"c": {"d": 4}}}}
assert unflatten({"a": [1, 2], "b.c": [3]}) == {"a": [1, 2], "b": {"c": [3]}}

# Custom separator
assert unflatten({"a/b": 1}, sep="/") == {"a": {"b": 1}}

# Round trip property
original = {"a": {"b": 1}, "c": {"d": {"e": 2}}, "f": 3}
assert unflatten(flatten(original)) == original

# Error handling: Conflict (Leaf is prefix of another key)
try:
    unflatten({"a": 1, "a.b": 2})
    assert False, "Should raise ValueError for prefix conflict"
except ValueError as e:
    assert "conflict" in str(e)

# Error handling: Conflict (Prefix is leaf of another key)
try:
    unflatten({"a.b": 2, "a": 1})
    assert False, "Should raise ValueError for prefix conflict"
except ValueError as e:
    assert "conflict" in str(e)

# Error handling: Conflict (Empty dict vs value)
try:
    unflatten({"a.b": 2, "a": {}})
    assert False, "Should raise ValueError for conflict with empty dict"
except ValueError as e:
    assert "conflict" in str(e)

# Error handling: Non-string keys in unflatten (split behavior)
# Note: unflatten uses split(), so keys must be strings to avoid AttributeError
try:
    unflatten({123: "a"})
    assert False, "Should raise AttributeError/TypeError if key is not string"
except (AttributeError, TypeError):
    pass
